def generate():
    for name, content in ICONS.items():
        path = os.path.join(ICONS_DIR, f"{name}.svg")
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
    print(f"Successfully generated {len(ICONS)} bright SVG icons in {ICONS_DIR}")

if __name__ == "__main__":
    generate()
